if (!aiReplyText || /apologies for the brief delay/i.test(aiReplyText)) {
  const guide = String(baseData.matchedScriptGuide || '').replace(/\r?\n+/g, ' ').trim();
  const lang = String(baseData.detectedLanguage || '').toLowerCase();
  if (guide) {
    aiReplyText = guide;
  } else if (lang.includes('tagalog') || lang.includes('taglish')) {
    aiReplyText = "Salamat sa message! Nandito ako para tumulong sa inyong Automation at Web App Projects (tulad ng AI chatbots, webhook/API integrations, at workflow automations). Anong specific na automation o web app project ang gusto ninyong ipagawa o i-automate?";
