  sbQueueNode = $('Supabase FIFO DM Queue (Enqueue & Acquire Turn)').first().json || {};
} catch (_) {}
const buildNode = $('Build DM Thread ID & Pipe Conversation').first().json || {};
let fmtNode = {};
try {
  fmtNode = $('Format AI Reply & Update Pipe History').first().json || {};
} catch (_) {}

const queueId = String(sbQueueNode.queueId || sbQueueNode.queue_id || buildNode.queueId || '').trim();
const messageId = String(buildNode.messageId || buildNode.dmThreadId || sbQueueNode.comment_id || '').trim();
const aiReplyText = String(fmtNode.aiReplyText || fmtNode.reply || '').trim();
const finalStatus = aiReplyText ? 'completed' : 'skipped_own_message';
const databaseUrl = (typeof process !== 'undefined' && process.env && process.env.DATABASE_URL) ? String(process.env.DATABASE_URL).trim() : '';

if (databaseUrl && queueId && (databaseUrl.startsWith('postgres://') || databaseUrl.startsWith('postgresql://'))) {
  try {
    const { Client } = require('pg');
    const client = new Client({
      connectionString: databaseUrl,
      ssl: databaseUrl.includes('localhost') ? false : { rejectUnauthorized: false }
    });
    await client.connect();
    await client.query(
      `UPDATE glennbot_comment_automation_queue
       SET status = $1, ai_reply = $2, completed_at = NOW()
       WHERE queue_id = $3`,
      [finalStatus, aiReplyText, queueId]
    );
    await client.end();
  } catch (_) {}
}

try {
  const httpMod = require('http');
  const port = (typeof process !== 'undefined' && process.env && process.env.PORT) ? process.env.PORT : 3000;
  const reqBody = JSON.stringify({ queue_id: queueId, comment_id: messageId, ai_reply: aiReplyText, status: finalStatus });
  await new Promise((resolve) => {
    const req = httpMod.request({
      hostname: '127.0.0.1',
      port,
      path: '/api/v1/automations/supabase-queue/complete',
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(reqBody) }
    }, (res) => {
      res.on('data', () => {});
      res.on('end', resolve);
    });
    req.on('error', resolve);
    req.write(reqBody);
    req.end();
  });
} catch (_) {}

return [{
  json: {
    status: 'success',
    queueId,
    messageId,
    queueStatus: finalStatus,
    aiReplyText,
    supabaseTable: 'glennbot_comment_automation_queue'
  }
}];
